#!/usr/bin/env bash
set -euo pipefail

# Run from the root of your local dhruvmankame/AI-SOC clone.
if [[ ! -d web || ! -d agents || ! -d supabase ]]; then
  echo "Run this script from the root of your AI-SOC repository (containing web/, agents/, and supabase/)." >&2
  exit 1
fi
if [[ -e ai-soc-frontend ]]; then
  echo "ai-soc-frontend/ already exists. Move it before re-running; no files were changed." >&2
  exit 1
fi
if [[ ! -f web/package.json ]]; then
  echo "The existing web/package.json is missing; nothing was changed." >&2
  exit 1
fi
if ! command -v python3 >/dev/null 2>&1; then
  echo "Python 3 is required to unpack this self-contained installer." >&2
  exit 1
fi
if ! command -v bun >/dev/null 2>&1 && ! command -v npm >/dev/null 2>&1; then
  echo "Install Bun or Node.js/npm first, then run this script again." >&2
  exit 1
fi
backup="web.backup.$(date +%Y%m%d-%H%M%S)"
if [[ -e "$backup" ]]; then
  echo "Backup destination $backup already exists; nothing was changed." >&2
  exit 1
fi

# The reviewed frontend source is embedded below; no network download is needed.
python3 - "$0" <<'PYEXTRACT'
import base64, io, pathlib, sys, zipfile
script = pathlib.Path(sys.argv[1]).read_bytes()
marker = b"\n__AI_SOC_FRONTEND_ARCHIVE_BASE64__\n"
if marker not in script:
    raise SystemExit("Embedded frontend archive was not found")
archive = base64.b64decode(script.split(marker, 1)[1].strip(), validate=True)
with zipfile.ZipFile(io.BytesIO(archive)) as z:
    names = z.namelist()
    if not names or any(
        not (name == "README.md" or name.startswith("ai-soc-frontend/"))
        or pathlib.PurePosixPath(name).is_absolute()
        or ".." in pathlib.PurePosixPath(name).parts
        for name in names
    ):
        raise SystemExit("Invalid archive contents")
    z.extractall(".")
print("Extracted the redesigned interface.")
PYEXTRACT

# Keep the original application intact and make the redesign the active web app.
mv web "$backup"
if ! mv ai-soc-frontend web; then
  mv "$backup" web
  echo "Could not activate the redesigned interface; original app restored." >&2
  exit 1
fi
if [[ -f "$backup/.env.local" && ! -e web/.env.local ]]; then
  cp "$backup/.env.local" web/.env.local
fi
echo "Original web/ saved as $backup/; the redesign is now web/."
cd web
if command -v bun >/dev/null 2>&1; then
  bun install
  if [[ "${1:-}" != "--install-only" ]]; then
    echo "Starting AI-SOC frontend (press Ctrl+C to stop)."
    bun run dev
  fi
else
  npm install
  if [[ "${1:-}" != "--install-only" ]]; then
    echo "Starting AI-SOC frontend (press Ctrl+C to stop)."
    npm run dev
  fi
fi
exit 0
__AI_SOC_FRONTEND_ARCHIVE_BASE64__

